// app/alternateUI/NewHeader.tsx
import React from "react";

interface NewHeaderProps {
  setShowCartResume: React.Dispatch<React.SetStateAction<boolean>>;
  itemQuantity: number;
}

export const NewHeader = ({ setShowCartResume, itemQuantity }: NewHeaderProps) => {
  return (
    <header className="new-header">
      <h1>UI Alternativa - Nueva Cabecera</h1>
      <button onClick={() => setShowCartResume(true)}>
        Ver resumen del carrito ({itemQuantity})
      </button>
    </header>
  );
};
