// components/UIChangerButton.tsx
import { useTheme } from "../context/ThemeContext";

export default function UIChangerButton() {
  const { isAlternateUI, toggleUI } = useTheme();

  return (
    <button onClick={toggleUI}>
      Cambiar a {isAlternateUI ? "UI predeterminada" : "UI alternativa"}
    </button>
  );
}
