// app/alternateUI/NewProductsContainer.tsx
import React from "react";

interface NewProductsContainerProps {
  itemQuantity: number;
  setItemQuantity: React.Dispatch<React.SetStateAction<number>>;
}

export const NewProductsContainer = ({
  itemQuantity,
  setItemQuantity,
}: NewProductsContainerProps) => {
  return (
    <div className="new-products-container">
      <h2>Productos (UI Alternativa)</h2>
      <p>Cantidad en carrito: {itemQuantity}</p>
      <button onClick={() => setItemQuantity(itemQuantity + 1)}>
        Agregar al carrito
      </button>
    </div>
  );
};
